#include "ludcmp.h"

void kernel_ludcmp(double A[40][40], double b[40], double x[40], double y[40]) {
    const int N = 40;

    // LU decomposition (Doolittle) in-place
    for (int i = 0; i < N; i++) {
        // lower triangular factors (L)
        for (int j = 0; j < i; j++) {
            double w = A[i][j];
            for (int k = 0; k < j; k++) {
                w -= A[i][k] * A[k][j];
            }
            A[i][j] = w / A[j][j];
        }
        // upper triangular factors (U)
        for (int j = i; j < N; j++) {
            double w = A[i][j];
            for (int k = 0; k < i; k++) {
                w -= A[i][k] * A[k][j];
            }
            A[i][j] = w;
        }
    }

    // Forward substitution: L y = b (L unit lower triangular)
    for (int i = 0; i < N; i++) {
        double w = b[i];
        for (int j = 0; j < i; j++) {
            w -= A[i][j] * y[j];
        }
        y[i] = w; // L(i,i) = 1
    }

    // Backward substitution: U x = y
    for (int i = N - 1; i >= 0; i--) {
        double w = y[i];
        for (int j = i + 1; j < N; j++) {
            w -= A[i][j] * x[j];
        }
        x[i] = w / A[i][i];
    }
}
```

